    // 두 사람의 점수예요.
    int kim = 70;
    int lee = 70;
    // p는 kim 칸을 가리켜요.
    int *p = &kim;
    // q도 p와 같은 칸을 가리키게 하려는 줄이에요.
    int *q = &lee;
    // 같은 칸을 가리키면 1, 아니면 0이 찍혀요.
    printf("p == q: %d\n", p == q);
    // 가리키는 두 칸의 값이 같으면 1이 찍혀요.
    printf("*p == *q: %d\n", *p == *q);
    // q를 거쳐 5점을 더해요.
    *q = *q + 5;
    printf("kim: %d, lee: %d\n", kim, lee);
    return 0;
}

