#include <stdio.h>

// 값을 복사해서 받아요. 바꿔도 복사본만 바뀌어요.
void swap_value(int x, int y) {
    // 잠깐 담아 둘 칸 t를 써서 맞바꿔요.
    int t = x;
    x = y;
    y = t;
    // 함수 안의 두 값을 출력해요.
    printf("함수 안: %d %d\n", x, y);
}

// 주소를 받아요. *x는 main의 칸 그 자체예요.
void swap_addr(int *x, int *y) {
    // 가리키는 두 칸의 값을 맞바꿔요.
    int t = *x;
    *x = *y;
    *y = t;
    // 함수 안에서 가리키는 두 칸을 출력해요.
    printf("함수 안: %d %d\n", *x, *y);
}

int main(void) {
    // 앞뒤 두 칸의 값이에요.
    int front = 9;
    int back = 4;
    // 앞 값이 더 크면 두 값을 바꿔 작은 값이 앞에 오게 해요.
    if (front > back) {
        swap_value(front, back);
    }
    // main의 두 칸을 출력해요.
    printf("main: %d %d\n", front, back);
    return 0;
}

