#include <stdio.h>

int main(void) {
    // 네 번 잰 온도예요.
    int temp[4] = {21, 25, 19, 30};
    // 몇 칸 옮길지예요. 칸이 4개라 3까지만 돼요.
    int step = 2;
    // p는 첫 칸을 가리켜요.
    int *p = temp;
    // step번 되풀이해요.
    for (int k = 0; k < step; k++) {
        // 다음 칸으로 옮기려는 줄이에요.
        (*p)++;
    }
    // p가 가리키는 칸과 첫 칸의 값을 봐요.
    printf("*p: %d\n", *p);
    printf("temp[0]: %d\n", temp[0]);
    return 0;
}

