#include <stdio.h>

// 상품 하나의 가격과 재고를 묶은 구조체예요.
struct Item {
    // 멤버 두 개예요. 상품마다 따로 가져요.
    int price;
    int stock;
};

int main(void) {
    // 깎아 줄 금액이에요.
    int cut = 500;
    // 상품 pen을 만들고 멤버에 차례로 값을 담아요.
    struct Item pen = {1500, 40};
    // copy에는 pen의 멤버가 통째로 복사돼요.
    struct Item copy = pen;
    // pen을 할인하려고 만든 포인터예요.
    struct Item *p = &copy;
    // 포인터로 멤버를 쓸 때는 ->를 써요.
    p->price = p->price - cut;
    // 변수로 멤버를 쓸 때는 .을 써요.
    printf("pen: %d원, 재고 %d\n", pen.price, pen.stock);
    printf("copy: %d원\n", copy.price);
    return 0;
}

